import { isNil } from 'lodash';
import { theme, fillObjectValues } from '@fiverr-private/theme';
export const getBreakpointCalc = (breakpointValue, slidesGap) => // 100% / the amount of visible slides - the total gap between the visible slides
"calc(100% / ".concat(breakpointValue, " - (").concat(slidesGap, " * (").concat(breakpointValue, " - 1) / ").concat(breakpointValue, "))");
const getSpacingValues = (source, target) => Object.keys(source).reduce((acc, key) => {
  acc[key] = target[source[key]];
  return acc;
}, {});
export const getMinWidth = (breakpoints, slidesGap) => {
  const defaultSlidesGap = typeof slidesGap === 'object' ? slidesGap : {
    default: slidesGap
  };
  const filledSlidesGapObject = fillObjectValues(breakpoints, 4, defaultSlidesGap);
  const spacingValues = getSpacingValues(filledSlidesGapObject, theme.numericSpacing);
  return Object.keys(breakpoints).reduce((acc, key) => {
    if (!isNil(breakpoints[key])) {
      acc[key] = getBreakpointCalc(breakpoints[key], "".concat(spacingValues[key], "px"));
    }
    return acc;
  }, {});
};