function ProfileStrengthCard() {
  const [score, setScore] = useState(7);
  const [fading, setFading] = useState(false);
  const isSmall = useMediaQuery('(max-width: 599px)');
  const maxScore = 13;
  const percent = Math.round((score / maxScore) * 100);

  const handleComplete = () => {
    if (score >= 9) return;
    setFading(true);
    setTimeout(() => {
      setScore((prev) => Math.min(prev + 1, 9));
      setFading(false);
    }, 300);
  };

  return (
    <Card variant="default" borderColor="border" padding="6" borderRadius="xl">
      <Stack direction="column" gap="4">
        <Stack
          direction="row"
          justifyContent="spaceBetween"
          alignItems="center"
        >
          <Heading as="h3" size="h_md">
            Profile strength
          </Heading>
          <Stack direction="row" gap="1" alignItems="baseline">
            <div
              style={{
                opacity: fading ? 0 : 1,
                transition: 'opacity 0.3s ease-in-out',
              }}
            >
              <Typography size="h_lg" fontWeight="bold" color="grey_1200">
                {score}
              </Typography>
            </div>
            <Typography size="b_lg" color="grey_1200">
              /13
            </Typography>
          </Stack>
        </Stack>
        <Text size="b_md" color="bodyPrimary">
          A strong profile helps you stand out and attract better opportunities.
        </Text>
        <ProgressLine percent={percent} />
        <Button
          variant="outline"
          size="md"
          onClick={handleComplete}
          fullWidth={isSmall}
        >
          Complete profile
        </Button>
      </Stack>
    </Card>
  );
}

