function SmallChoiceGroup({
  value,
  onChange,
}: {
  value: string | null;
  onChange: (v: string | null) => void;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [itemWidth, setItemWidth] = useState(0);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const items = el.querySelectorAll<HTMLElement>('[data-choice-item]');
    items.forEach((item) => {
      item.style.width = 'auto';
    });
    let max = 0;
    items.forEach((item) => {
      max = Math.max(max, item.offsetWidth);
    });
    setItemWidth(max);
  }, []);

  return (
    <div
      ref={containerRef}
      style={{
        display: 'flex',
        flexDirection: 'row',
        gap: '8px',
        overflowX: 'auto',
        WebkitOverflowScrolling: 'touch',
        scrollbarWidth: 'none',
      }}
    >
      {SMALL_CHOICE_ITEMS.map((item) => {
        const selected = value === item.value;
        return (
          <div
            key={item.value}
            data-choice-item=""
            onClick={() => onChange(item.value)}
            style={{
              width: itemWidth > 0 ? itemWidth : undefined,
              boxSizing: 'border-box',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'flex-start',
              gap: '4px',
              padding: '12px 16px',
              borderRadius: '8px',
              border: selected ? '2px solid #222325' : '1px solid #dadbdd',
              cursor: 'pointer',
              flexShrink: 0,
            }}
          >
            {item.icon}
            <Typography size="b_sm" fontWeight="bold" color="grey_1200">
              {item.label}
            </Typography>
            <Typography size="b_sm" color="grey_900">
              {item.count}
            </Typography>
          </div>
        );
      })}
    </div>
  );
}

