// ── Penta Motion: dropdown animation helpers ────────────────────────────────
// Open:  Fast 2 (320ms) ease-out  — scale(0.97)+blur(4px) → fully open
// Close: Fast 1 (200ms) ease-in   — fully open → scale(0.97)+blur(4px)

const EASE_OUT_ENTER = 'cubic-bezier(0.16, 1, 0.3, 1)'; // --ease-out
const EASE_IN_EXIT = 'cubic-bezier(0.6, 0.05, 0.75, 0.2)'; // --ease-in

// Penta Motion — one speed faster than the mega-menu panel:
// Open:  --duration-fast-2 (320ms) · --ease-out · --blur-sm (8px) · transform-origin top right
// Close: --duration-fast-1 (200ms) · --ease-in
const getDropdownAnimStyle = (isVisible: boolean, origin: React.CSSProperties['transformOrigin'] = 'top right'): React.CSSProperties => ({
  opacity: isVisible ? 1 : 0,
  transform: isVisible ? 'scale(1) translateY(0px)' : 'scale(0.98) translateY(-8px)',
  filter: isVisible ? 'blur(0px)' : 'blur(8px)', // --blur-sm
  transformOrigin: origin,
  transition: isVisible
    ? `opacity 320ms ${EASE_OUT_ENTER}, transform 320ms ${EASE_OUT_ENTER}, filter 320ms ${EASE_OUT_ENTER}` // --duration-fast-2
    : `opacity 200ms ${EASE_IN_EXIT}, transform 200ms ${EASE_IN_EXIT}, filter 200ms ${EASE_IN_EXIT}`,       // --duration-fast-1
  pointerEvents: isVisible ? 'auto' : 'none',
});

// Content fades in after Fast 1 delay (200ms = --duration-fast-1), roughly 60% into the
// container's Fast 2 (320ms) open animation.
const getDropdownContentAnimStyle = (isVisible: boolean): React.CSSProperties => ({
  opacity: isVisible ? 1 : 0,
  transition: isVisible
    ? `opacity 200ms ${EASE_OUT_ENTER} 200ms` // delay: --duration-fast-1
    : `opacity 150ms ${EASE_IN_EXIT}`,
});

// Two-phase hook: isOpen gates DOM presence, isVisible drives the CSS transition
function useDropdownState() {
  const [isOpen, setIsOpen] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);

  const open = useCallback(() => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    setIsOpen(true);
    // Two rAFs: first to mount, second to trigger the transition from initial state
    requestAnimationFrame(() => requestAnimationFrame(() => setIsVisible(true)));
  }, []);

  const close = useCallback(() => {
    setIsVisible(false); // start exit animation
    closeTimer.current = setTimeout(() => setIsOpen(false), 210); // remove after Fast 1
  }, []);

  const toggle = useCallback(() => {
    if (isOpen) close();
    else open();
  }, [isOpen, open, close]);

  useEffect(() => {
    if (!isOpen) return;
    const handleMouseDown = (e: MouseEvent) => {
      if (!wrapperRef.current?.contains(e.target as Node)) close();
    };
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
    };
    document.addEventListener('mousedown', handleMouseDown);
    document.addEventListener('keydown', handleKey);
    return () => {
      document.removeEventListener('mousedown', handleMouseDown);
      document.removeEventListener('keydown', handleKey);
    };
  }, [isOpen, close]);

  return { isOpen, isVisible, open, close, toggle, wrapperRef };
}

// Reusable vertical scroll-fade: shows a white gradient at the bottom when content overflows
function ScrollFade({ children, style }: { children: React.ReactNode; style?: React.CSSProperties }) {
  const ref = useRef<HTMLDivElement>(null);
  const [hasMore, setHasMore] = useState(false);
  const check = useCallback(() => {
    const el = ref.current;
    if (el) setHasMore(el.scrollHeight > el.clientHeight + el.scrollTop + 1);
  }, []);
  useEffect(() => { requestAnimationFrame(check); }, [check]);
  return (
    // flex column so the inner scroll div can use flex:1 to fill exactly the remaining space
    <div style={{ position: 'relative', flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
      <div ref={ref} onScroll={check} style={{ overflowY: 'auto', flex: 1, minHeight: 0, ...style }}>
        {children}
      </div>
      {hasMore && (
        <div style={{
          position: 'absolute', bottom: 0, left: 0, right: 0, height: 48,
          background: 'linear-gradient(to bottom, rgba(255,255,255,0) 0%, rgba(255,255,255,1) 100%)',
          pointerEvents: 'none',
        }} />
      )}
    </div>
  );
}

