import { findChildByType, getComponentProps } from '@fiverr-private/ui_utils';
import { TRACK_ID } from '../Track/constants';
import { SLIDES_INDICATOR_ID } from '../SlidesIndicator/constants';
export const getChildren = children => {
  const Track = findChildByType(children, TRACK_ID);
  const Slides = getComponentProps(Track).children || [];
  const SlidesIndicator = findChildByType(children, SLIDES_INDICATOR_ID);
  return {
    Track,
    Slides,
    SlidesIndicator
  };
};